exec('import csv,os,requests,pandas as pd\nfrom datetime import datetime\nfrom zoneinfo import ZoneInfo\nstate_file="intraday_alert_state.csv"; now_paris=datetime.now(ZoneInfo("Europe/Paris")); now_utc=pd.Timestamp.now(tz="UTC"); decisions=list(csv.DictReader(open("intraday_decisions.csv",encoding="utf-8"))) if os.path.exists("intraday_decisions.csv") else []; old=list(csv.DictReader(open(state_file,encoding="utf-8"))) if os.path.exists(state_file) else []; notified={(r["ticker"],r["signal_date"],r["session_date"]):r.get("decision","") for r in old}; notified_at={(r["ticker"],r["signal_date"],r["session_date"]):r.get("notified_at_paris","") for r in old}; allowed=("ACHAT CONFIRME","ACHAT REACTIVE","SETUP INITIAL INVALIDE","EXPIRE"); sent=0\ndef num(value):\n try: return format(float(value),".2f")\n except: return "N/A"\ndef parse_time(value):\n try:\n  ts=pd.Timestamp(value); return ts.tz_localize("Europe/Paris") if ts.tzinfo is None else ts\n except: return None\nfor r in decisions:\n key=(r.get("ticker",""),r.get("signal_date",""),r.get("session_date","")); current=r.get("decision",""); previous=notified.get(key,"")\n if current not in allowed or current==previous: continue\n decision_ts=parse_time(r.get("decision_time","")); fresh=False; age_minutes=None; decision_paris=None\n if decision_ts is not None:\n  decision_paris=decision_ts.tz_convert("Europe/Paris"); age_minutes=(now_utc-decision_ts.tz_convert("UTC")).total_seconds()/60; fresh=decision_paris.date()==now_paris.date() and 0<=age_minutes<=10\n devise="EUR" if r.get("ticker","").endswith((".PA",".AS")) else "USD"\n if fresh:\n  icon="✅" if current=="ACHAT CONFIRME" else "🔄" if current=="ACHAT REACTIVE" else "⚠️" if current=="SETUP INITIAL INVALIDE" else "⌛"; title=icon+" "+current; status_line="État suivant : "+r.get("next_state",""); action_line="Décision récente et actionnable en paper trading."\n else:\n  title="🕘 ÉVÉNEMENT HISTORIQUE DÉTECTÉ"; status_line="Statut historique : "+current; action_line="⚠️ Décision périmée. Aucun achat ne doit être exécuté."\n decision_text=decision_paris.strftime("%d/%m/%Y à %H:%M, heure de Paris") if decision_paris is not None else "Heure indisponible"; age_text=(format(age_minutes,".0f")+" min") if age_minutes is not None else "indisponible"; text="<b>"+title+"</b>\\n\\n<b>"+r.get("ticker","")+"</b>\\nDécision : "+decision_text+"\\nTraitement : "+now_paris.strftime("%d/%m/%Y à %H:%M, heure de Paris")+"\\nÂge de la décision : "+age_text+"\\n\\nPrix décision : "+num(r.get("decision_close"))+" "+devise+"\\nVWAP : "+num(r.get("vwap"))+"\\nOR haut : "+num(r.get("opening_range_high"))+" "+devise+"\\nOR bas : "+num(r.get("opening_range_low"))+" "+devise+"\\nVolume : "+num(r.get("decision_volume"))+"\\n\\nMotif : "+r.get("reason","")+"\\n"+status_line+"\\n\\n<b>"+action_line+"</b>\\n\\n<i>Paper trading uniquement.</i>"; response=requests.post("https://api.telegram.org/bot"+os.environ["TELEGRAM_BOT_TOKEN"]+"/sendMessage",data={"chat_id":os.environ["TELEGRAM_CHAT_ID"],"text":text,"parse_mode":"HTML"},timeout=30); ok=response.status_code==200 and response.json().get("ok")\n print(r.get("ticker",""),current,"| fresh",fresh,"| age",round(age_minutes,1) if age_minutes is not None else "N/A","min | Telegram",response.status_code,ok)\n if ok: notified[key]=current; notified_at[key]=now_paris.isoformat(timespec="seconds"); sent+=1\nfields=["ticker","signal_date","session_date","decision","notified_at_paris"]\nwith open(state_file,"w",newline="",encoding="utf-8") as q:\n w=csv.DictWriter(q,fieldnames=fields); w.writeheader(); w.writerows({"ticker":k[0],"signal_date":k[1],"session_date":k[2],"decision":v,"notified_at_paris":notified_at.get(k,"")} for k,v in notified.items())\nprint("Alertes envoyées :",sent)')
